CREATE OR REPLACE FUNCTION get_emp_grade(p_emp_id numeric) RETURNS varchar
LANGUAGE plpgsql AS $fn$
#variable_conflict use_column
DECLARE
  v_salary employees.base_salary%TYPE;
  v_rating varchar(10);
BEGIN
  SELECT base_salary, COALESCE(perf_rating, 'U') INTO STRICT v_salary, v_rating FROM employees WHERE emp_id = p_emp_id;
  RETURN NULLIF(CONCAT(CASE v_rating WHEN 'A' THEN 'G1' WHEN 'B' THEN 'G2' WHEN 'C' THEN 'G3' WHEN 'U' THEN 'UNRATED' ELSE 'G4' END, '-', CASE WHEN v_salary >= 100000 THEN 'SENIOR' ELSE 'STANDARD' END), '');
EXCEPTION
  WHEN no_data_found THEN
    RETURN NULL;
END;
$fn$;

CREATE SCHEMA IF NOT EXISTS payroll_pkg;
CREATE OR REPLACE FUNCTION payroll_pkg.net_pay(p_gross numeric) RETURNS numeric
LANGUAGE plpgsql AS $fn$
#variable_conflict use_column
BEGIN
  RETURN ROUND(COALESCE(p_gross, 0) * (1 - 0.10), 2);
END;
$fn$;

CREATE OR REPLACE FUNCTION top_earners(p_dept_id numeric, p_n numeric) RETURNS varchar
LANGUAGE plpgsql AS $fn$
#variable_conflict use_column
DECLARE
  v_list varchar(4000);
  r record;
BEGIN
  FOR r IN SELECT full_name FROM (SELECT full_name FROM employees WHERE dept_id = p_dept_id AND status = 'ACTIVE' ORDER BY base_salary DESC, emp_id LIMIT CAST(GREATEST(COALESCE(FLOOR(p_n), 0), 0) AS BIGINT)) LOOP
    v_list := NULLIF(CONCAT(v_list, CASE WHEN NOT v_list IS NULL THEN ', ' END, r.full_name), '');
  END LOOP;
  RETURN v_list;
END;
$fn$;

CREATE OR REPLACE PROCEDURE apply_raise(p_emp_id numeric, p_pct numeric, p_new_salary OUT numeric)
LANGUAGE plpgsql AS $fn$
#variable_conflict use_column
DECLARE
  v_old employees.base_salary%TYPE;
BEGIN
  SELECT base_salary INTO STRICT v_old FROM employees WHERE emp_id = p_emp_id FOR UPDATE;
  p_new_salary := ROUND(v_old * (1 + CAST(p_pct AS DECIMAL) / 100), 2);
  UPDATE employees SET base_salary = p_new_salary WHERE emp_id = p_emp_id;
EXCEPTION
  WHEN no_data_found THEN
    p_new_salary := -1;
END;
$fn$;

CREATE OR REPLACE PROCEDURE calc_bonus(p_emp_id numeric, p_override varchar, p_bonus OUT numeric)
LANGUAGE plpgsql AS $fn$
#variable_conflict use_column
BEGIN
  p_override := NULLIF(p_override, '');
  DECLARE
    v_salary employees.base_salary%TYPE;
    v_rating employees.perf_rating%TYPE;
  BEGIN
    SELECT base_salary, perf_rating INTO STRICT v_salary, v_rating FROM employees WHERE emp_id = p_emp_id;
    IF NOT p_override IS NULL THEN
      v_rating := p_override;
    END IF;
    IF v_rating = 'A' THEN
      p_bonus := ROUND(v_salary * 0.20, 2);
    ELSIF v_rating = 'B' THEN
      p_bonus := ROUND(v_salary * 0.10, 2);
    ELSIF v_rating IS NULL THEN
      p_bonus := 0;
    ELSE
      p_bonus := ROUND(v_salary * 0.05, 2);
    END IF;
  END;
END;
$fn$;

CREATE OR REPLACE PROCEDURE monthly_payroll(p_run_date timestamp(0), p_rows_out OUT numeric)
LANGUAGE plpgsql AS $fn$
#variable_conflict use_column
DECLARE
  v_month_start timestamp(0) := DATE_TRUNC('MONTH', p_run_date);
  v_month_end timestamp(0) := DATE_TRUNC('MONTH', DATE_TRUNC('DAY', p_run_date)) + INTERVAL '1 month - 1 day' + (DATE_TRUNC('DAY', p_run_date) - DATE_TRUNC('DAY', DATE_TRUNC('DAY', p_run_date)));
  v_days_in_m numeric := EXTRACT(EPOCH FROM (v_month_end - v_month_start)) / 86400 + 1;
  v_days numeric;
  v_allow numeric;
  v_gross numeric(12, 2);
  e record;
BEGIN
  p_rows_out := 0;
  FOR e IN SELECT emp_id, hire_date, base_salary FROM employees WHERE status = 'ACTIVE' AND hire_date <= v_month_end ORDER BY emp_id LOOP
    v_days := EXTRACT(EPOCH FROM (v_month_end - GREATEST(DATE_TRUNC('DAY', e.hire_date), v_month_start))) / 86400 + 1;
    v_allow := CASE WHEN e.hire_date > CASE WHEN DATE_TRUNC('DAY', v_month_end) = DATE_TRUNC('MONTH', v_month_end) + INTERVAL '1 month - 1 day' THEN DATE_TRUNC('MONTH', v_month_end) + (CAST(TRUNC(-6) AS INT) + 1) * INTERVAL '1 MONTH' - INTERVAL '1 DAY' + (v_month_end - DATE_TRUNC('DAY', v_month_end)) ELSE v_month_end + CAST(TRUNC(-6) AS INT) * INTERVAL '1 MONTH' END THEN 0 ELSE 2500 END;
    v_gross := ROUND(CAST(CAST(e.base_salary AS DECIMAL) / 12 * v_days AS DECIMAL) / v_days_in_m, 2) + v_allow;
    INSERT INTO payroll_runs (run_id, emp_id, pay_month, gross_pay, days_worked, created_at) VALUES (NEXTVAL('payroll_run_seq'), e.emp_id, v_month_start, v_gross, v_days, p_run_date);
    p_rows_out := p_rows_out + 1;
  END LOOP;
END;
$fn$;

CREATE SCHEMA IF NOT EXISTS payroll_pkg;
CREATE OR REPLACE PROCEDURE payroll_pkg.close_month(p_pay_month timestamp(0), p_total OUT numeric)
LANGUAGE plpgsql AS $fn$
#variable_conflict use_column
BEGIN
  SELECT COALESCE(SUM(payroll_pkg.net_pay(gross_pay)), 0) INTO STRICT p_total FROM payroll_runs WHERE pay_month = DATE_TRUNC('MONTH', p_pay_month);
END;
$fn$;

CREATE OR REPLACE FUNCTION emp_salary_audit_trg_fn() RETURNS trigger
LANGUAGE plpgsql AS $fn$
#variable_conflict use_column
BEGIN
  INSERT INTO salary_audit (audit_id, emp_id, old_salary, new_salary, changed_on, change_type) VALUES (NEXTVAL('salary_audit_seq'), NEW.emp_id, OLD.base_salary, NEW.base_salary, DATE_TRUNC('DAY', CAST(DATE_TRUNC('SECOND', STATEMENT_TIMESTAMP()) AS TIMESTAMP(0))), CASE WHEN NEW.base_salary > OLD.base_salary THEN 'RAISE' ELSE 'CUT' END);
  RETURN NULL;
END;
$fn$;

CREATE OR REPLACE TRIGGER emp_salary_audit_trg
AFTER update of base_salary ON employees
FOR EACH ROW
WHEN (NEW.base_salary <> OLD.base_salary)
EXECUTE FUNCTION emp_salary_audit_trg_fn();
